def is_inside_notes(path: str) -> bool:
    """True when path is relative and never climbs above the notes directory."""
    ex is_inside_notes("a.txt") == True
    ex is_inside_notes("sub/../a.txt") == True
    ex is_inside_notes("..") == False
    ex is_inside_notes("/etc/passwd") == False
    ex is_inside_notes("sub/../../x") == False
    if path.startswith("/"):
        return False
    depth = 0
    for seg in path.split("/"):
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            depth -= 1
            if depth < 0:
                return False
        else:
            depth += 1
    return True

def read_public(path: str) -> str uses fs:
    """Text of notes/path when path stays inside notes, else the empty string."""
    post out == "" or is_inside_notes(path)
    if not is_inside_notes(path):
        return ""
    with fs = fs.sub("notes"):
        text = fs.read(path) else ""
        return text
